// Normalize the webhook request: the competition slug is the only required input.
const body = $json.body ?? {};
if (!body.competition) {
  throw new Error('Body must include "competition" (Kaggle slug)');
}
const maxIterations = Math.round(Number(body.max_iterations ?? 3));
return [{
  json: {
    competition: body.competition,
    submit: body.submit === true,
    sample_frac: body.sample_frac ?? 1,
    max_iterations: Number.isFinite(maxIterations) ? Math.min(Math.max(maxIterations, 1), 10) : 3,
    goal: body.goal ?? 'Reach the top 20% of the public leaderboard',
  },
}];

// What the Planner sees: the goal, the data profile and what has been tried before.
const input = $('Read input').first().json;
return [{
  json: {
    attempt_id: $('Start attempt').first().json.attempt_id,
    context: {
      goal: input.goal,
      iterations_in_this_attempt: input.max_iterations,
      profile: $('Profile data').first().json,
      history: $('Get history').first().json,
    },
  },
}];

// Start of an iteration (one training run). The plan is the Planner's until the
// LB Reviewer revises it; the focus comes from the previous iteration's feedback.
// Finished iterations are kept by "Record iteration" (its latest run has them all).
const input = $('Read input').first().json;
const planner = $('Planner').first().json;
const iterations = $('Record iteration').isExecuted ? $('Record iteration').first().json.iterations : [];
const last = iterations[iterations.length - 1];
const revised = $('LB Reviewer').isExecuted ? $('LB Reviewer').first().json : null;

return [{
  json: {
    attempt_id: $('Start attempt').first().json.attempt_id,
    iteration: iterations.length + 1,
    max_iterations: input.max_iterations,
    iterations,
    plan: {
      source: revised ? 'lb_reviewer' : 'planner',
      strategy: revised ? revised.plan : planner.strategy,
      focus: last ? last.next_focus : planner.focus_for_this_attempt,
    },
  },
}];

// What the Data agent sees: the data profile, the current plan and focus, and past runs.
const it = $('Iteration context').first().json;
// Runs trained on another share of the data are not comparable, so they are left out.
const history = $('Refresh history').first().json;
const sampleFrac = $('Read input').first().json.sample_frac;
return [{
  json: {
    attempt_id: it.attempt_id,
    context: {
      iteration: `${it.iteration} of ${it.max_iterations}`,
      plan: it.plan,
      profile: $('Profile data').first().json,
      external_datasets: $('Discover external data').first().json.accepted ?? [],
      history: { ...history, recent: history.recent.filter((r) => r.sample_frac === sampleFrac) },
    },
  },
}];

// What the Modeling agent sees: task, plan, chosen features and past runs.
const profile = $('Profile data').first().json;
const it = $('Iteration context').first().json;
// Runs trained on another share of the data are not comparable, so they are left out.
const history = $('Refresh history').first().json;
const sampleFrac = $('Read input').first().json.sample_frac;
return [{
  json: {
    attempt_id: it.attempt_id,
    context: {
      task: profile.task,
      train_rows: profile.train_rows,
      n_features: profile.n_features,
      iteration: `${it.iteration} of ${it.max_iterations}`,
      plan: it.plan,
      feature_config: $('Data agent').first().json,
      history: { ...history, recent: history.recent.filter((r) => r.sample_frac === sampleFrac) },
    },
  },
}];

// Guardrails between the agents and the worker: agent output is checked against
// the allowed options and corrected rather than trusted. Every correction is
// reported so it shows up in the trace.
const profile = $('Profile data').first().json;
const planner = $('Planner').first().json;
const it = $('Iteration context').first().json;
const history = $('Refresh history').first().json;
const data = $('Data agent').first().json;
const modeling = $('Modeling agent').first().json;
const input = $('Read input').first().json;
const adjustments = [];

const METRIC = /^(rmse|rmsle|mae|roc_auc|log_loss|accuracy|f1|map@\d+)$/;
let metric = String(planner.metric ?? '').toLowerCase();
if (!METRIC.test(metric)) {
  adjustments.push(`metric '${planner.metric}' is not supported; using ${profile.suggested_metric}`);
  metric = profile.suggested_metric;
}

const columns = Object.keys(profile.features);
const knownColumns = (field) => {
  const requested = data[field] ?? [];
  const unknown = requested.filter((c) => !columns.includes(c));
  if (unknown.length) adjustments.push(`${field}: ignored unknown columns ${unknown.join(', ')}`);
  return requested.filter((c) => columns.includes(c));
};

const RANGES = {
  lightgbm: {
    learning_rate: [0.005, 0.3], num_leaves: [8, 512], max_depth: [-1, 16], min_child_samples: [5, 500],
    reg_alpha: [0, 100], reg_lambda: [0, 100], subsample: [0.3, 1], colsample_bytree: [0.2, 1],
    n_estimators: [100, 10000],
  },
  xgboost: {
    learning_rate: [0.005, 0.3], max_depth: [1, 16], min_child_weight: [0, 100], gamma: [0, 20],
    reg_alpha: [0, 100], reg_lambda: [0, 100], subsample: [0.3, 1], colsample_bytree: [0.2, 1],
    n_estimators: [100, 10000],
  },
};
const INTEGER_PARAMS = new Set(['num_leaves', 'max_depth', 'min_child_samples', 'n_estimators']);

const DEFAULTS = {
  lightgbm: { learning_rate: 0.05, num_leaves: 63, max_depth: -1, min_child_samples: 20, reg_alpha: 0,
    reg_lambda: 0, subsample: 0.8, colsample_bytree: 0.8, n_estimators: 3000 },
  xgboost: { learning_rate: 0.05, max_depth: 6, min_child_weight: 1, gamma: 0, reg_alpha: 0, reg_lambda: 1,
    subsample: 0.8, colsample_bytree: 0.8, n_estimators: 3000 },
};
// The training rows are part of the feature set: adding external data is a feature change.
const featureKey = (f, externalData) => JSON.stringify([
  [...(f.drop ?? [])].sort(), [...(f.frequency_encode ?? [])].sort(), [...(f.as_category ?? [])].sort(),
  [...(f.target_encode ?? [])].sort(), [...(f.digit_features ?? [])].sort(), f.add_null_count === true,
  [...(externalData ?? [])].sort(),
]);
const effective = (m, p) => ({ ...DEFAULTS[m], ...p });
const runs = [history.best_full_data_run, history.best_full_data_model_run, ...(history.recent ?? [])]
  .filter(Boolean).filter((r) => r.sample_frac === input.sample_frac);
const done = (config, duplicate) => [{
  json: { config, adjustments, duplicate_of: duplicate ? duplicate.run_id : null },
}];
const note = `iteration ${it.iteration}: ${it.plan.focus ?? ''}`;

// A blend averages the predictions of earlier runs; only runs that saved their
// predictions and were trained on the same rows can take part.
const best = history.best_full_data_model_run;
let model = modeling.model;
if (model === 'blend') {
  const requested = [...new Set(modeling.blend_runs ?? [])];
  const usable = requested.filter((id) => runs.some((r) => r.run_id === id && r.blendable && r.model !== 'blend'));
  const rejected = requested.filter((id) => !usable.includes(id));
  if (rejected.length) {
    adjustments.push(`blend: ignored runs ${rejected.join(', ')} (unknown, a blend, another sample size or `
      + 'trained before predictions were saved)');
  }
  if (usable.length >= 2) {
    const key = JSON.stringify([...usable].sort());
    const tried = runs.find((r) => r.model === 'blend' && JSON.stringify([...(r.blend_runs ?? [])].sort()) === key);
    if (tried) adjustments.push(`blend repeats run ${tried.run_id} (cv ${tried.cv_score}); training skipped`);
    return done({ metric, model: 'blend', blend_runs: usable, sample_frac: input.sample_frac, note }, tried);
  }
  // A requested run that only lacks saved predictions is retrained as it was, so the
  // next iteration can blend it.
  const missing = runs.find((r) => rejected.includes(r.run_id) && !r.blendable && r.model !== 'blend');
  if (missing) {
    adjustments.push(`blend needs two usable runs; retraining run ${missing.run_id} as it was so it can be blended`);
    return done({ metric, model: missing.model, params: missing.params,
      features: { target_encode: [], digit_features: [], ...missing.features }, external_data: missing.external_data ?? [],
      sample_frac: input.sample_frac, note }, null);
  }
  adjustments.push('blend needs two usable runs; training the best single-model run\'s configuration instead');
  model = best?.model ?? 'lightgbm';
}

if (!RANGES[model]) {
  adjustments.push(`model '${model}' is not supported; using lightgbm`);
  model = 'lightgbm';
}

const params = {};
for (const [name, value] of Object.entries(modeling.params ?? {})) {
  const range = RANGES[model][name];
  if (!range || typeof value !== 'number' || !Number.isFinite(value)) {
    adjustments.push(`param '${name}' ignored (not allowed for ${model})`);
    continue;
  }
  let safe = Math.min(Math.max(value, range[0]), range[1]);
  if (INTEGER_PARAMS.has(name)) safe = Math.round(safe);
  if (safe !== value) adjustments.push(`param '${name}' adjusted ${value} -> ${safe}`);
  params[name] = safe;
}

// External datasets: only the ones discovery accepted for this competition.
const acceptedExternal = ($('Discover external data').first().json.accepted ?? []).map((d) => d.name);
const externalData = [...new Set(data.external_data ?? [])].filter((name) => {
  if (acceptedExternal.includes(name)) return true;
  adjustments.push(`external_data: ignored unknown dataset ${name}`);
  return false;
});

const hasNulls = Object.values(profile.features).some((f) => f.null_pct > 0);
if (data.add_null_count === true && !hasNulls) {
  adjustments.push('add_null_count disabled: the data has no missing values');
}

const features = {
  drop: knownColumns('drop'),
  frequency_encode: knownColumns('frequency_encode'),
  as_category: knownColumns('as_category'),
  target_encode: knownColumns('target_encode').filter((c) => !(data.drop ?? []).includes(c)),
  digit_features: knownColumns('digit_features').filter((c) => profile.features[c]?.min !== undefined),
  add_null_count: data.add_null_count === true && hasNulls,
};

// Attribution: one kind of change per iteration relative to a reference run, so
// the effect on the score can be read from the result. The reference is the best
// run of the proposed model with the proposed features if one exists (then up to
// two hyperparameters may change), else the best run of that model (or the best
// single-model run if the model was never trained). If the features differ from
// the reference, the params stay as in the reference.
const LOWER_IS_BETTER = /^(rmse|rmsle|mae|log_loss)$/;
const bestOf = (list) => list.reduce((a, b) => {
  if (!a) return b;
  const better = LOWER_IS_BETTER.test(metric) ? b.cv_score < a.cv_score : b.cv_score > a.cv_score;
  return better ? b : a;
}, null);
const ofModel = runs.filter((r) => r.model === model);
const ref = bestOf(ofModel.filter((r) => featureKey(r.features, r.external_data) === featureKey(features, externalData))) ?? bestOf(ofModel) ?? best;
if (ref && RANGES[ref.model]) {
  const refParams = effective(ref.model, ref.params);
  if (featureKey(features, externalData) !== featureKey(ref.features, ref.external_data)) {
    const ownParams = effective(model, params);
    const paramsChanged = model !== ref.model
      || Object.keys(refParams).some((k) => ownParams[k] !== refParams[k]);
    if (paramsChanged) {
      adjustments.push(`features changed vs reference run ${ref.run_id}: model and params reset to that run's `
        + `(${ref.model} ${JSON.stringify(ref.params)}) to isolate the feature effect`);
      model = ref.model;
      for (const k of Object.keys(params)) delete params[k];
      Object.assign(params, ref.params);
    }
  } else if (model === ref.model) {
    const ownParams = effective(model, params);
    const changed = Object.keys(ownParams).filter((k) => ownParams[k] !== refParams[k]);
    for (const k of changed.slice(2)) {
      adjustments.push(`param '${k}' reverted to the reference run's value ${refParams[k]}: at most two `
        + `hyperparameter changes per iteration`);
      if (k in ref.params) params[k] = ref.params[k];
      else delete params[k];
    }
  }
}

// Repeats add no information, except retraining a run from before predictions
// were saved, which makes it available for blending.
const matches = runs.filter((r) => r.model === model && featureKey(r.features, r.external_data) === featureKey(features, externalData)
  && JSON.stringify(effective(r.model, r.params)) === JSON.stringify(effective(model, params)));
const tried = matches.find((r) => r.blendable) ?? null;
if (tried) {
  adjustments.push(`configuration repeats run ${tried.run_id} (cv ${tried.cv_score}); training skipped`);
} else if (matches.length) {
  adjustments.push(`configuration repeats run ${matches[0].run_id}, which has no saved predictions; retrained so it can be blended`);
}

return done({ metric, model, params, features, external_data: externalData, sample_frac: input.sample_frac, note }, tried);

// What the Evaluator sees: the run that just finished and the best earlier full-data run.
const run = $('Train').first().json;
return [{
  json: {
    attempt_id: $('Start attempt').first().json.attempt_id,
    context: {
      run: {
        run_id: run.run_id,
        metric: run.metric,
        higher_is_better: run.higher_is_better,
        cv_score: run.cv_score,
        cv_std: run.cv_std,
        fold_scores: run.fold_scores,
        best_iterations: run.best_iterations,
        sample_frac: run.config.sample_frac,
        model: run.config.model,
        params: run.config.params,
        features: run.config.features,
        top_features: run.top_features.slice(0, 8),
        blend: run.blend,
      },
      best_previous_full_data_run: $('Refresh history').first().json.best_full_data_run,
    },
  },
}];

// What the LB Reviewer sees at the end of every iteration: the team's position on
// the public leaderboard (from its best submission so far), how far the goal is,
// what the team tried in this attempt and the plan it was following.
const input = $('Read input').first().json;
const it = $('Iteration context').first().json;
const run = $('Train').first().json;
let submission;
try {
  submission = $('Submit').isExecuted ? $('Submit').first()?.json : undefined;
} catch {
  submission = undefined;
}
const submitted = submission?.run_id === run.run_id;
const lb = $('Leaderboard').first().json;
const gap = lb.higher_is_better
  ? lb.top20_threshold - lb.best_public_score
  : lb.best_public_score - lb.top20_threshold;

return [{
  json: {
    attempt_id: it.attempt_id,
    run_id: run.run_id,
    context: {
      goal: input.goal,
      data_has_missing_values: Object.values($('Profile data').first().json.features).some((f) => f.null_pct > 0),
      iteration: `${it.iteration} of ${it.max_iterations}`,
      current_plan: it.plan,
      this_run: {
        run_id: run.run_id,
        cv_score: run.cv_score,
        cv_std: run.cv_std,
        submitted,
        public_score: submitted ? submission.public_score : null,
        model: run.config.model,
        params: run.config.params,
        features: run.config.features,
      },
      leaderboard: {
        rank: lb.rank,
        teams: lb.teams,
        top_percent: lb.top_percent,
        our_best_public_score: lb.best_public_score,
        top20_threshold: lb.top20_threshold,
        leader_score: lb.best_score,
        higher_is_better: lb.higher_is_better,
        gap_to_top20: Number(gap.toFixed(5)),
      },
      earlier_iterations: it.iterations,
      history: $('Refresh history').first().json.recent.filter((r) => r.sample_frac === input.sample_frac),
    },
  },
}];

// End of an iteration: record what happened and decide whether to loop again.
// Nodes inside the loop keep the output of earlier iterations, so a node only
// counts for this iteration when its output refers to this iteration's run.
const it = $('Iteration context').first().json;
const built = $('Build train config').first().json;
const latest = (node, branch = 0) => {
  try {
    return $(node).isExecuted ? $(node).first(branch)?.json : undefined;
  } catch {
    return undefined;
  }
};

const finish = (record) => {
  let stopReason = null;
  if (record.top_percent <= 20) stopReason = `goal reached: top ${record.top_percent}%`;
  else if (record.reviewer_stop) stopReason = 'LB Reviewer stopped the attempt';
  else if (it.iteration >= it.max_iterations) stopReason = `iteration budget used (${it.max_iterations})`;
  return [{
    json: {
      attempt_id: it.attempt_id,
      record,
      iterations: [...it.iterations, record],
      continue: stopReason === null,
      stop_reason: stopReason,
    },
  }];
};

// The guardrails skipped training: the proposal (after corrections) repeated an
// earlier run. Agents tend to propose the same thing again, so the focus moves to
// another step of the plan, and two skips in a row end the attempt.
if (built.duplicate_of) {
  let skipsInRow = 1;
  for (let i = it.iterations.length - 1; i >= 0 && it.iterations[i].skipped; i--) skipsInRow++;
  const otherSteps = (it.plan.strategy ?? []).filter((step) => step !== it.plan.focus);
  const nextStep = otherSteps[(skipsInRow - 1) % Math.max(otherSteps.length, 1)];
  const record = {
    iteration: it.iteration,
    focus: it.plan.focus,
    skipped: `configuration repeats run ${built.duplicate_of}`,
    guardrail_adjustments: built.adjustments,
    next_focus: `${nextStep ?? 'A change not tried yet'} (the previous proposal was not trained: `
      + `${built.adjustments.join('; ')}. Propose a configuration that is not in the history.)`,
  };
  const result = finish(record);
  if (skipsInRow >= 2 && result[0].json.continue) {
    Object.assign(result[0].json, { continue: false, stop_reason: 'agents repeated earlier runs twice in a row' });
  }
  return result;
}

const train = $('Train').first().json;
const evaluation = $('Evaluator').first().json;
const submission = latest('Submit');
const submitted = submission?.run_id === train.run_id;
const wantedToSubmit = $('Read input').first().json.submit && evaluation.submit === true;
const reviewed = latest('Reviewer context')?.run_id === train.run_id;
const reviewer = reviewed ? $('LB Reviewer').first().json : null;
const lb = reviewed ? latest('Leaderboard') : undefined;

const record = {
  iteration: it.iteration,
  focus: it.plan.focus,
  run_id: train.run_id,
  cv_score: train.cv_score,
  cv_std: train.cv_std,
  higher_is_better: train.higher_is_better,
  model: train.config.model,
  params: train.config.params,
  features: train.config.features,
  guardrail_adjustments: built.adjustments,
  verdict: evaluation.verdict,
  submitted,
  next_focus: reviewer ? reviewer.focus_for_next_iteration : evaluation.next_focus,
};
if (reviewer) record.lb_assessment = reviewer.assessment;
if (reviewer?.stop === true) record.reviewer_stop = true;
if (submitted) record.public_score = submission.public_score;
if (lb?.rank) {
  Object.assign(record, {
    rank: lb.rank,
    teams: lb.teams,
    top_percent: lb.top_percent,
    best_public_score: lb.best_public_score,
    top20_threshold: lb.top20_threshold,
  });
}
if (wantedToSubmit && !submitted) {
  const error = latest('Submit', 1);
  record.submit_error = error?.error?.message ?? error?.error ?? 'submission did not complete';
}

return finish(record);

// Outcome of the attempt: every iteration, the best run and the latest leaderboard position.
const loop = $('Record iteration').first().json;
const iterations = loop.iterations;
const higherIsBetter = iterations.find((i) => i.run_id)?.higher_is_better ?? true;
const best = iterations.filter((i) => i.run_id).reduce((a, b) => {
  if (!a) return b;
  return (higherIsBetter ? b.cv_score > a.cv_score : b.cv_score < a.cv_score) ? b : a;
}, null);

const summary = {
  iterations: iterations.length,
  stop_reason: loop.stop_reason,
  best_run: best && { iteration: best.iteration, run_id: best.run_id, cv_score: best.cv_score, model: best.model },
  submissions: iterations.filter((i) => i.submitted).length,
  history: iterations.map((i) => ({
    iteration: i.iteration,
    cv_score: i.cv_score,
    verdict: i.verdict ?? i.skipped,
    public_score: i.public_score,
    top_percent: i.top_percent,
    guardrail_adjustments: i.guardrail_adjustments.length,
  })),
};
const lastReviewed = [...iterations].reverse().find((i) => i.rank);
if (lastReviewed) {
  const { best_public_score, rank, teams, top_percent, top20_threshold } = lastReviewed;
  Object.assign(summary, { best_public_score, rank, teams, top_percent, top20_threshold });
}
return [{ json: { summary } }];
